WITH exploded AS (SELECT id, log_ts, level, status_code, key, v FROM app_logs LATERAL VIEW EXPLODE(context) li AS key, v), flattened_attrs AS (SELECT id, log_ts, status_code, key, CAST((status_code & 1) != 0 AS INT) AS is_flagged, SHIFTRIGHT(status_code, 2) AS status_code_high FROM exploded WHERE HOUR(log_ts) BETWEEN 8 AND 16), enriched AS (SELECT id, status_code, key, NTILE(10) OVER w_grp AS status_code_bucket, SUM(status_code_high) OVER w_grp_2 AS cumulative_status_code_high, FIRST_VALUE(key, TRUE) OVER w_grp_2 AS first_known_key FROM flattened_attrs WINDOW w_grp AS (ORDER BY status_code DESC, id ASC, key ASC), w_grp_2 AS (PARTITION BY key ORDER BY status_code ASC, id ASC, key ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), with_windows AS (SELECT id, status_code, key, status_code_bucket, first_known_key, AVG(status_code) OVER (PARTITION BY key) AS key_avg_status_code, LAG(cumulative_status_code_high, 1) OVER w_ordered AS prev_cumulative_status_code_high, SUM(status_code_bucket) OVER (PARTITION BY key ORDER BY status_code ASC, id ASC, key ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_status_code_bucket, RANK() OVER w_hist AS status_code_bucket_rank FROM enriched WHERE status_code >= 267 WINDOW w_ordered AS (PARTITION BY key ORDER BY cumulative_status_code_high ASC, id ASC, key ASC), w_hist AS (PARTITION BY key ORDER BY status_code_bucket ASC)), latest AS (SELECT * FROM with_windows QUALIFY ROW_NUMBER() OVER (PARTITION BY key ORDER BY status_code_bucket ASC NULLS LAST, id ASC, key ASC) = 1), filtered AS (SELECT *, status_code_bucket_rank * key_avg_status_code AS status_code_bucket_rank_times_key_avg_status_code, status_code - running_status_code_bucket AS status_code_minus_running_status_code_bucket, COALESCE(key, 'OTHER') AS resolved_key FROM latest WHERE key IS NOT NULL AND key IS DISTINCT FROM 'version'), ranked AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY key ORDER BY status_code DESC, id ASC, key ASC) AS dedup_rank FROM filtered QUALIFY dedup_rank = 1) SELECT CASE WHEN prev_cumulative_status_code_high >= 10 THEN 'PREMIUM' ELSE 'STANDARD' END AS prev_cumulative_status_code_high_tier, CASE WHEN status_code_bucket >= 7 THEN 'LARGE' ELSE 'SMALL' END AS status_code_bucket_tier, SORT_ARRAY(COLLECT_SET(key)) AS key_list, AVG(status_code_bucket_rank) FILTER (WHERE key = 'trace') AS trace_avg_status_code_bucket_rank, ROUND(AVG(status_code_bucket_rank_times_key_avg_status_code), 2) AS avg_status_code_bucket_rank_times_key_avg_status_code, SUM(CASE WHEN key = 'trace' THEN running_status_code_bucket ELSE 0 END) AS trace_running_status_code_bucket, COUNT(*) FILTER (WHERE key = 'version') AS version_rows FROM ranked GROUP BY ROLLUP (CASE WHEN prev_cumulative_status_code_high >= 10 THEN 'PREMIUM' ELSE 'STANDARD' END, CASE WHEN status_code_bucket >= 7 THEN 'LARGE' ELSE 'SMALL' END) ORDER BY status_code_bucket_tier DESC NULLS LAST;
